mapper.select:
SELECT COUNT(*) FROM ai_connection c
WHERE c.deleted_at IS NULL
AND c.enabled = #{enabled}

mapper.update:
UPDATE ai_connection SET provider_catalog_id = #{providerCatalogId}, name = #{name}, base_url = #{baseUrl}, endpoint_path = #{endpointPath}, protocol = #{protocol},
credential_ciphertext = #{credentialCiphertext}, credential_iv = #{credentialIv}, credential_key_version = #{credentialKeyVersion}, credential_masked = #{credentialMasked},
enabled = #{enabled}, timeout_ms = #{timeoutMs}, input_price_per_million = #{inputPricePerMillion}, output_price_per_million = #{outputPricePerMillion}, last_test_status = #{lastTestStatus}, configuration_version = configuration_version + 1, updated_at = #{updatedAt} WHERE id = #{id} AND deleted_at IS NULL AND configuration_version = #{configurationVersion}

UPDATE ai_connection SET last_test_status = #{status}, last_tested_at = #{testedAt},
  last_test_latency_ms = #{latencyMs}, last_error_code = #{errorCode},
  last_error_summary = #{errorSummary}, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{id}
  AND deleted_at IS NULL
  AND configuration_version = #{expectedVersion}
